// GERADO por scratchpad/make_fonts.py — não editar à mão.
// Sora 600 (títulos) e Source Sans 3 400/600 (corpo), instâncias estáticas
// subsetadas em Latin + pontuação, a partir dos woff2 variáveis de docs/prototipos.
// jsPDF só embute TTF (glyf); por isso a conversão. Sem itálico verdadeiro:
// os estilos itálicos reaproveitam o peso reto (a distinção fica na cor/tamanho).
import type jsPDF from 'jspdf';

const SORA_600 = '';
const SS3_400 = '';
const SS3_600 = '';

export const PDF_FONT_HEAD = 'Sora';
export const PDF_FONT_BODY = 'SourceSans3';

let registered = false;

/** Registra Sora e Source Sans 3 no documento. Idempotente por documento novo. */
export function registerPdfFonts(doc: jsPDF): void {
  doc.addFileToVFS('Sora-600.ttf', SORA_600);
  doc.addFont('Sora-600.ttf', PDF_FONT_HEAD, 'normal');
  doc.addFont('Sora-600.ttf', PDF_FONT_HEAD, 'bold');
  doc.addFileToVFS('SS3-400.ttf', SS3_400);
  doc.addFileToVFS('SS3-600.ttf', SS3_600);
  doc.addFont('SS3-400.ttf', PDF_FONT_BODY, 'normal');
  doc.addFont('SS3-600.ttf', PDF_FONT_BODY, 'bold');
  doc.addFont('SS3-400.ttf', PDF_FONT_BODY, 'italic');
  doc.addFont('SS3-600.ttf', PDF_FONT_BODY, 'bolditalic');
  registered = true;
}

export function pdfFontsRegistered(): boolean { return registered; }
